insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1845,15,43,'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ','613aef186fdfd5af0b1b2b474ef579114656ccb64c23f03c58705ff130e18b80',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1846,15,44,'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ','e52b468d6e96a244ffb765bbaedaf5edd0b27b94f3f127074b58ba21eca49d47',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1847,15,45,'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَعُيُونٍ','0559f9f243e34b2959349907d6edbeaf0618c5171063610586daf755abf1272f',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1848,15,46,'ٱدْخُلُوهَا بِسَلَـٰمٍ ءَامِنِينَ','79d9e6fc8ba2430bb9f248bbb990319615b726872cac732579bcc7a740fd62d2',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1849,15,47,'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَـٰبِلِينَ','5dfbdddd1abbc5fabf901b8f2410f3ea25172e154228056fb77663100e92b4b8',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1850,15,48,'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ','768ef4403f9770f6264df27fb54b1951dee2529159632542b0b2b73e3702718a',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1851,15,49,'نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ','917f5355cf2e1f7f0643be18f763edd5319da897ae0c2ad5c420396605c1f9ee',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1852,15,50,'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ','29d41e2444d54b8770968a3343f68261d69f112cbb4a4733304a054c5799ab79',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1853,15,51,'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ','3b7dcddbe1e9cd447b22da9073421efc9bd43357767165a25b99522b1ed00f3a',14,264,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1854,15,52,'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَـٰمًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ','0d9422e270595179a2cde7c651cb6ecce553fafb6d7131d2c063f97f581f5948',14,265,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1855,15,53,'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ عَلِيمٍ','127ebe559054f32db0b9cdee729ab2242544f137f701b94d3693e6d3c56c6bb0',14,265,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1856,15,54,'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ','d3140cf9fe189af239e18d3a9a2b159afdf2e68e42adae0479f16ebceae7aef6',14,265,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1857,15,55,'قَالُوا۟ بَشَّرْنَـٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَـٰنِطِينَ','1f92134f6ea2d77c6d984eaeb6926c7abab1fc0432b0fa129a665a0ce17f6660',14,265,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1858,15,56,'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ','2a3f59061996ec6886a4973e4a27d900f4c10f8394d401d2e0f0e421c599c2ea',14,265,1);
